:root {
  --bg-board: #fdf6ee;
  --bg-card: #ffffff;
  --bg-tag: #f2e8d9;
  --color-accent: #8b5e3c;
  --color-accent-light: #c49a6c;
  --color-title: #3b2710;
  --color-subtitle: #7a5c3e;
  --color-origin: #a07850;
  --color-price: #8b5e3c;
  --color-tag-text: #6b4226;
  --color-footer: #9a7254;
  --color-border: #e5d4be;
  --color-label-bg: #8b5e3c;
  --color-label-text: #fdf6ee;
  --color-divider: #c49a6c;
  --color-footer-bg: #f2e8d9;
}

.cheese-board {
  background-color: var(--bg-board);
  border: 2px solid var(--color-border);
  border-radius: 16px;
  padding: 20px;
  width: 520px;
  max-width: 520px;
}

.board-header {
  text-align: center;
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.board-label {
  background-color: var(--color-label-bg);
  color: var(--color-label-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  padding: 3px 10px;
  border-radius: 20px;
}

.board-title {
  font-size: 26px;
  font-weight: 800;
  color: var(--color-title);
  margin: 0;
  line-height: 1.1;
}

.board-subtitle {
  font-size: 13px;
  color: var(--color-subtitle);
  margin: 0;
  font-style: italic;
}

.cheese-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 14px;
}

.cheese-card {
  background-color: var(--bg-card);
  border: 1.5px solid var(--color-border);
  border-radius: 12px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.cheese-top {
  display: flex;
  align-items: center;
  gap: 8px;
}

.cheese-icon {
  font-size: 22px;
  line-height: 1;
  flex-shrink: 0;
}

.cheese-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.cheese-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-title);
  line-height: 1.2;
}

.cheese-origin {
  font-size: 11px;
  color: var(--color-origin);
  font-weight: 400;
}

.cheese-price {
  font-size: 16px;
  font-weight: 800;
  color: var(--color-price);
  flex-shrink: 0;
}

.cheese-tags {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}

.tag {
  background-color: var(--bg-tag);
  color: var(--color-tag-text);
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
  border: 1px solid var(--color-border);
}

.board-footer {
  background-color: var(--color-footer-bg);
  border: 1.5px solid var(--color-border);
  border-radius: 10px;
  padding: 8px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.footer-item {
  font-size: 12px;
  color: var(--color-footer);
  font-weight: 500;
}

.footer-divider {
  color: var(--color-divider);
  font-weight: 300;
}
